#[doc = "    \"enforce_cross_agent_quarantine\": {"]
#[doc = "      \"title\": \"Enforce Cross Agent Quarantine\","]
#[doc = "      \"description\": \"If True, the orchestrator must automatically emit global QuarantineIntents to sever infected SemanticEdges across the swarm to prevent epistemic contagion.\","]
#[doc = "      \"type\": \"boolean\""]
#[doc = "    },"]
#[doc = "    \"epistemic_quarantine_threshold\": {"]
#[doc = "      \"title\": \"Epistemic Quarantine Threshold\","]
#[doc = "      \"description\": \"The minimum certainty boundary. If an event's propagated confidence drops below this threshold, it is structurally quarantined.\","]
#[doc = "      \"type\": \"number\","]
#[doc = "      \"maximum\": 1.0,"]
#[doc = "      \"minimum\": 0.0"]
